/* From Uiverse.io by kamehame-ha - Tags: input, modern, clean */
.__UIV_SCOPE__ .coolinput {
  display: flex;
  flex-direction: column;
  width: fit-content;
  position: static;
  max-width: 240px;
}

.__UIV_SCOPE__ .coolinput label.text {
  font-size: 0.75rem;
  color: #818CF8;
  font-weight: 700;
  position: relative;
  top: 0.5rem;
  margin: 0 0 0 7px;
  padding: 0 3px;
  background: #e8e8e8;
  width: fit-content;
}

.__UIV_SCOPE__ .coolinput input[type=text].input {
  padding: 11px 10px;
  font-size: 0.75rem;
  border: 2px #818CF8 solid;
  border-radius: 5px;
  background: #e8e8e8;
}

.__UIV_SCOPE__ .coolinput input[type=text].input:focus {
  outline: none;
}
